/**
 * Injected by Vite's `define` (see vite.config.ts). They exist so a
 * performance log can name the build it came from: two laps are only
 * comparable if the code is the same, and the log used to record the world
 * seed and the device while saying nothing about the version.
 */
declare const __APP_VERSION__: string
declare const __APP_COMMIT__: string
